stages.css:
.page{background:#f5f6fa}
header.top{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;padding:10px 14px;background:#1d2a4d;color:#fff}
.logo{font-weight:800;letter-spacing:.02em}
nav a{color:#d9e1ff;text-decoration:none;margin-left:12px;font-size:14px;padding-bottom:2px}
nav a[aria-current=page],nav a.active{color:#fff;border-bottom:2px solid #ffb703}
.hero{padding:20px 14px;background:linear-gradient(135deg,#2457d6,#6a3fd1);color:#fff}
.hero h1{margin:0 0 6px;font-size:22px;line-height:1.2}
.hero p{margin:0 0 12px;opacity:.9}
.btn{display:inline-block;padding:9px 16px;border-radius:8px;border:0;background:#ffb703;color:#1d2330;font-weight:700;text-decoration:none}
.btn.ghost{background:transparent;border:2px solid currentColor;color:inherit}
main{padding:14px}
h2{font-size:17px;margin:0 0 8px}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px}
.card{background:#fff;border-radius:10px;padding:12px;box-shadow:0 1px 3px rgba(0,0,0,.14)}
footer{padding:12px 14px;background:#e6e9f2;color:#55607a;font-size:13px}
.tag{display:inline-block;background:#e63946;color:#fff;font:700 12px/1 system-ui,sans-serif;padding:4px 7px;border-radius:999px;margin-right:6px;vertical-align:2px}
[hidden]{display:none!important}

