stages.chk:
function (root) {
    var c = root.querySelector(".cards");
    root.querySelector("#listBtn").click();
    if (!c.classList.contains("list")) return "After clicking List, .cards should have the class list.";
    root.querySelector("#gridBtn").click();
    if (c.classList.contains("list")) return "After clicking Grid, the list class should be gone.";
    return true;
  }

stages.s:
const cards = document.querySelector(".cards");
document.querySelector("#listBtn").addEventListener("click", () => {
  cards.classList.add("list");
});
document.querySelector("#gridBtn").addEventListener("click", () => {
  cards.classList.remove("list");
});

