stages.chk:
function (root) {
    var sws = root.querySelectorAll(".swatch");
    sws[1].click();
    var v = getComputedStyle(root).getPropertyValue("--accent").trim().toLowerCase();
    if (v !== "#2ec4b6") return "After clicking Teal, --accent should be #2ec4b6. It's " + (v || "not set") + ".";
    sws[2].click();
    v = getComputedStyle(root).getPropertyValue("--accent").trim().toLowerCase();
    if (v !== "#ff6b9a") return "After clicking Pink, --accent should be #ff6b9a.";
    return true;
  }

stages.s:
const swatches = document.querySelectorAll(".swatch");
swatches.forEach(btn => {
  btn.addEventListener("click", () => {
    document.body.style.setProperty("--accent", btn.dataset.color);
  });
});

