stages.chk:
function (root) {
    var b = root.querySelector("#theme");
    b.click();
    if (!root.classList.contains("dark")) return "After one click, document.body should have the class dark.";
    if (b.textContent.trim() !== "☀ Light mode") return "When dark, the button should say ☀ Light mode.";
    if (b.getAttribute("aria-pressed") !== "true") return "When dark, aria-pressed should be \"true\".";
    b.click();
    if (root.classList.contains("dark")) return "A second click should turn dark mode off.";
    if (b.textContent.trim() !== "☾ Dark mode" || b.getAttribute("aria-pressed") !== "false") return "When light, the button should say ☾ Dark mode with aria-pressed \"false\".";
    return true;
  }

stages.s:
const btn = document.querySelector("#theme");
btn.addEventListener("click", () => {
  document.body.classList.toggle("dark");
  const dark = document.body.classList.contains("dark");
  btn.textContent = dark ? "☀ Light mode" : "☾ Dark mode";
  btn.setAttribute("aria-pressed", String(dark));
});

