function (root) {
    var c = root.querySelectorAll("#chart .col");
    if (c.length !== 4) return "There should be 4 .col bars in #chart. Found " + c.length + ".";
    var want = [["Rocket Run", 60], ["Slime Farm", 100], ["Pixel Golf", 25], ["Moon Maze", 80]];
    for (var i = 0; i < 4; i++) {
      if (Math.abs(parseFloat(c[i].style.height) - want[i][1]) > 0.5 || !/%$/.test(c[i].style.height)) return want[i][0] + " should be " + want[i][1] + "% tall. It's " + (c[i].style.height || "not set") + ".";
      if (c[i].title !== want[i][0] || c[i].textContent.trim() !== want[i][0]) return "Bar " + (i + 1) + " needs the title and text " + want[i][0] + ".";
    }
    return true;
  }

stages.s:
const plays = [
  { game: "Rocket Run", count: 300 },
  { game: "Slime Farm", count: 500 },
  { game: "Pixel Golf", count: 125 },
  { game: "Moon Maze", count: 400 }
];
const chart = document.querySelector("#chart");
const top = Math.max(...plays.map(p => p.count));
for (const p of plays) {
  const col = document.createElement("div");
  col.className = "col";
  col.style.height = (p.count / top * 100) + "%";
  col.title = p.game;
  col.textContent = p.game;
  chart.append(col);
}

