function (root) {
    var t = root.querySelectorAll(".trend");
    var want = [["up", "▲ 12"], ["down", "▼ 4"], ["flat", "– 0"]];
    for (var i = 0; i < 3; i++) {
      if (!t[i].classList.contains(want[i][0])) return "The trend with data-change " + t[i].dataset.change + " needs the class " + want[i][0] + ".";
      if (t[i].textContent.trim() !== want[i][1]) return "The trend with data-change " + t[i].dataset.change + " should read " + want[i][1] + ". It reads " + (t[i].textContent || "nothing") + ".";
    }
    return true;
  }

stages.s:
document.querySelectorAll(".trend").forEach(el => {
  const n = Number(el.dataset.change);
  if (n > 0) {
    el.classList.add("up");
    el.textContent = "▲ " + n;
  } else if (n < 0) {
    el.classList.add("down");
    el.textContent = "▼ " + Math.abs(n);
  } else {
    el.classList.add("flat");
    el.textContent = "– 0";
  }
});

