stages.chk:
function (root) {
    var b = root.querySelectorAll(".filter"), li = root.querySelectorAll("#bugs li");
    var vis = function () { return [].filter.call(li, function (x) { return !x.hidden; }).map(function (x) { return x.dataset.status; }).join(","); };
    b[1].click();
    if (vis() !== "open,open") return "After clicking Open, only the 2 open bugs should show.";
    if (!b[1].classList.contains("active") || b[0].classList.contains("active")) return "The clicked button should be the only one with class active.";
    b[2].click();
    if (vis() !== "done,done") return "After clicking Done, only the 2 done bugs should show.";
    b[0].click();
    if (vis().split(",").length !== 4) return "After clicking All, every bug should show again.";
    if (!b[0].classList.contains("active") || b[2].classList.contains("active")) return "Only All should be active now.";
    return true;
  }

stages.s:
const buttons = document.querySelectorAll(".filter");
const items = document.querySelectorAll("#bugs li");
buttons.forEach(btn => {
  btn.addEventListener("click", () => {
    const show = btn.dataset.show;
    items.forEach(li => {
      li.hidden = show !== "all" && li.dataset.status !== show;
    });
    buttons.forEach(b => b.classList.toggle("active", b === btn));
  });
});

