function (root) {
    var a = root.querySelectorAll("nav a");
    if (a.length !== 4) return "The nav should have 4 links. Found " + a.length + ".";
    var want = [["Games", "#games", 0], ["Blog", "#blog", 0], ["About", "#about", 0], ["GitHub", "https://github.com", 1]];
    for (var i = 0; i < 4; i++) {
      if (a[i].textContent !== want[i][0] || a[i].getAttribute("href") !== want[i][1]) return "Link " + (i + 1) + " should say " + want[i][0] + " and go to " + want[i][1] + ".";
      if (want[i][2] && (a[i].target !== "_blank" || a[i].rel !== "noopener")) return "The external GitHub link needs target _blank and rel noopener.";
      if (!want[i][2] && a[i].target === "_blank") return "Only external links should open in a new tab. " + want[i][0] + " is on our own site.";
    }
    return true;
  }

stages.s:
const links = [
  { text: "Games", href: "#games" },
  { text: "Blog", href: "#blog" },
  { text: "About", href: "#about" },
  { text: "GitHub", href: "https://github.com", external: true }
];
const nav = document.querySelector("nav");
for (const link of links) {
  const a = document.createElement("a");
  a.href = link.href;
  a.textContent = link.text;
  if (link.external) {
    a.target = "_blank";
    a.rel = "noopener";
  }
  nav.append(a);
}

