async function (root, logs, ex, code, t) {
    var bar = root.querySelector("#bar"), max = root.scrollHeight - root.clientHeight;
    root.scrollTop = Math.round(max / 2); root.dispatchEvent(new Event("scroll")); await t.wait(60);
    var w = parseFloat(bar.style.width);
    if (!/%$/.test(bar.style.width) || Math.abs(w - root.scrollTop / max * 100) > 1.5) return "Halfway down, #bar should be about 50% wide. It's " + (bar.style.width || "not set") + ".";
    root.scrollTop = max; root.dispatchEvent(new Event("scroll")); await t.wait(60);
    if (Math.abs(parseFloat(bar.style.width) - 100) > 1.5) return "At the bottom, #bar should be 100% wide.";
    root.scrollTop = 0; root.dispatchEvent(new Event("scroll"));
    return true;
  }

stages.s:
const bar = document.querySelector("#bar");
window.addEventListener("scroll", () => {
  const most = document.body.scrollHeight - document.body.clientHeight;
  bar.style.width = (window.scrollY / most * 100) + "%";
});

