function (root) {
    var s = root.querySelectorAll(".slide"), w = root.querySelector("#where");
    var cur = function () { var v = [].filter.call(s, function (x) { return !x.hidden; }); return v.length === 1 ? [].indexOf.call(s, v[0]) : -1; };
    if (cur() !== 0 || w.textContent.trim() !== "1 / 4") return "At the start, only slide 1 should show and #where should read 1 / 4.";
    root.querySelector("#next").click();
    if (cur() !== 1 || w.textContent.trim() !== "2 / 4") return "After ›, only slide 2 should show with 2 / 4.";
    root.querySelector("#prev").click(); root.querySelector("#prev").click();
    if (cur() !== 3 || w.textContent.trim() !== "4 / 4") return "Going back from slide 1 should wrap around to slide 4 (4 / 4).";
    root.querySelector("#next").click();
    if (cur() !== 0) return "Going forward from the last slide should wrap to slide 1.";
    return true;
  }

stages.s:
const slides = document.querySelectorAll(".slide");
let index = 0;
function show() {
  slides.forEach((s, n) => { s.hidden = n !== index; });
  document.querySelector("#where").textContent = (index + 1) + " / " + slides.length;
}
document.querySelector("#next").addEventListener("click", () => {
  index = (index + 1) % slides.length;
  show();
});
document.querySelector("#prev").addEventListener("click", () => {
  index = (index - 1 + slides.length) % slides.length;
  show();
});
show();

