stages.chk:
function (root) {
    var b = root.querySelector("#menuBtn"), n = root.querySelector("nav");
    b.click();
    if (!n.classList.contains("open") || b.getAttribute("aria-expanded") !== "true") return "After one click, the nav should have class open and the button aria-expanded=\"true\".";
    b.click();
    if (n.classList.contains("open") || b.getAttribute("aria-expanded") !== "false") return "A second click should close it and set aria-expanded=\"false\".";
    return true;
  }

stages.s:
const menuBtn = document.querySelector("#menuBtn");
const nav = document.querySelector("nav");
menuBtn.addEventListener("click", () => {
  const open = nav.classList.toggle("open");
  menuBtn.setAttribute("aria-expanded", String(open));
});

