stages.chk:
function (root) {
    var m = root.querySelector("#modal");
    root.querySelector("#openBtn").click();
    if (m.hidden) return "Clicking #openBtn should show #modal.";
    root.querySelector("#closeBtn").click();
    if (!m.hidden) return "Clicking ✕ should hide #modal.";
    root.querySelector("#openBtn").click();
    window.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape" }));
    if (!m.hidden) return "Pressing Escape should hide #modal.";
    return true;
  }

stages.s:
const modal = document.querySelector("#modal");
document.querySelector("#openBtn").addEventListener("click", () => {
  modal.hidden = false;
});
document.querySelector("#closeBtn").addEventListener("click", () => {
  modal.hidden = true;
});
document.addEventListener("keydown", e => {
  if (e.key === "Escape") modal.hidden = true;
});

