stages.chk:
function (root) {
    var f = root.querySelector("#contact"), em = root.querySelector("#email"), ms = root.querySelector("#message"), err = root.querySelector("#err");
    var send = function (a, b) { em.value = a; ms.value = b; if (f.requestSubmit) f.requestSubmit(); else f.dispatchEvent(new Event("submit", { cancelable: true })); };
    send("kit.example.com", "Hello there, nice games!");
    if (err.textContent !== "Please enter a valid email.") return "An email without @ should show: Please enter a valid email.";
    send("kit@example.com", "   hi    ");
    if (err.textContent !== "Please write at least 10 characters.") return "A short message (after trimming) should show: Please write at least 10 characters.";
    if (!f.hidden && !root.querySelector("#thanks").hidden) return "Don't show #thanks while there's an error.";
    send("kit@example.com", "Hello there, nice games!");
    if (err.textContent !== "") return "When everything's fine, #err should be empty.";
    if (!f.hidden || root.querySelector("#thanks").hidden) return "When everything's fine, hide the form and show #thanks.";
    return true;
  }

stages.s:
const form = document.querySelector("#contact");
const err = document.querySelector("#err");
form.addEventListener("submit", e => {
  e.preventDefault();
  const email = document.querySelector("#email").value;
  const message = document.querySelector("#message").value;
  if (!email.includes("@")) {
    err.textContent = "Please enter a valid email.";
  } else if (message.trim().length < 10) {
    err.textContent = "Please write at least 10 characters.";
  } else {
    err.textContent = "";
    form.hidden = true;
    document.querySelector("#thanks").hidden = false;
  }
});

