stages.chk:
function (root, logs, ex) {
    var a = root.querySelectorAll("nav a");
    if (a.length !== 3) return "The nav should have 3 links, one per page. Found " + a.length + ".";
    var want = [["Home", "#home"], ["Games", "#games"], ["About", "#about"]];
    for (var i = 0; i < 3; i++) if (a[i].textContent !== want[i][0] || a[i].getAttribute("href") !== want[i][1]) return "Link " + (i + 1) + " should say " + want[i][0] + " with href " + want[i][1] + ".";
    var v = function () { return [].filter.call(root.querySelectorAll(".view"), function (x) { return !x.hidden; }).map(function (x) { return x.dataset.page; }).join(","); };
    var cur = function () { return [].filter.call(a, function (x) { return x.getAttribute("aria-current") === "page"; }).map(function (x) { return x.textContent; }).join(","); };
    if (v() !== "home" || cur() !== "Home") return "The site should start on home, with only Home marked aria-current.";
    a[2].click();
    if (v() !== "about" || cur() !== "About") return "Clicking About should show only the about page and move aria-current to About.";
    if (typeof ex.showPage !== "function") return "Write a function called showPage.";
    ex.showPage("games");
    if (v() !== "games" || cur() !== "Games") return "showPage(\"games\") should show only the games page and mark Games.";
    root.querySelector("#theme").click();
    if (!root.classList.contains("dark")) return "#theme should turn on the dark class.";
    root.querySelector("#theme").click();
    if (root.classList.contains("dark")) return "Clicking #theme again should turn dark mode off.";
    return true;
  }

stages.s:
const pages = [
  { id: "home", title: "Home" },
  { id: "games", title: "Games" },
  { id: "about", title: "About" }
];
const nav = document.querySelector("nav");
for (const page of pages) {
  const a = document.createElement("a");
  a.href = "#" + page.id;
  a.textContent = page.title;
  a.addEventListener("click", e => {
    e.preventDefault();
    showPage(page.id);
  });
  nav.append(a);
}
function showPage(id) {
  document.querySelectorAll(".view").forEach(v => { v.hidden = v.dataset.page !== id; });
  nav.querySelectorAll("a").forEach(a => {
    if (a.getAttribute("href") === "#" + id) a.setAttribute("aria-current", "page");
    else a.removeAttribute("aria-current");
  });
}
document.querySelector("#theme").addEventListener("click", () => {
  document.body.classList.toggle("dark");
});
showPage("home");

